import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.Arrays;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine());int[] coins = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());int totalSum = 0;for (int i = 0; i < n; i++) {coins[i] = Integer.parseInt(st.nextToken());totalSum += coins[i];}Arrays.sort(coins);int mySum = 0;int count = 0;for (int i = n - 1; i >= 0; i--) {mySum += coins[i];count++;if (mySum > totalSum - mySum) {break;}}System.out.println(count);}}